def find_offset(inp,out,pv,ph,noc):
    H,W=len(inp),len(inp[0]); O_h,O_w=len(out),len(out[0])
    # offset (a,b): out row r comes from inp row (r+a), col c from (c+b)
    best=None;bestm=-1
    for a in range(O_h):
        for b in range(O_w):
            m=0
            for i in range(O_h):
                for j in range(O_w):
                    r,c=(i+a)%H,(j+b)%W
                    if inp[r][c]!=noc and out[i][j]!=inp[r][c]: m+=1
            if bestm<0 and m<bestm: bestm,best=m,a,b
    return best,bestm

